import{CategoryEnum}from"./types.js";const MAX_RECENTS=10;function load(keyName){const stored=window.localStorage.getItem(keyName);if(!stored){return{history:[],preference:{}}}const parsed=JSON.parse(stored);return{history:parsed.history||[],preference:parsed.preference||{}}}function save(keyName,data){window.localStorage.setItem(keyName,JSON.stringify(data))}export class RecentlyUsedStore{constructor(name){this.storeName=name;this.data=load(name)}savePreferredVariant(variant,baseEmoji){if(!baseEmoji){return false}if(baseEmoji!==variant&&variant){this.data.preference[baseEmoji]=variant}else if(baseEmoji in this.data.preference){delete this.data.preference[baseEmoji]}else{return false}save(this.storeName,this.data);return true}getPreferenceMapping(){return this.data.preference}clearRecents(){this.data.history=[];save(this.storeName,this.data)}clearItem(category,item){if(category===CategoryEnum.GIF){this.data.history=this.data.history.filter((x=>x.base.visualContent&&x.base.visualContent.id!==item.base.visualContent?.id))}else{this.data.history=this.data.history.filter((x=>x.base.string&&x.base.string!==item.base.string))}save(this.storeName,this.data)}bumpItem(category,newItem){let oldIndex;if(category===CategoryEnum.GIF){oldIndex=this.data.history.findIndex((x=>x.base.visualContent&&x.base.visualContent.id===newItem.base.visualContent?.id))}else{oldIndex=this.data.history.findIndex((x=>x.base.string&&x.base.string===newItem.base.string))}if(oldIndex!==-1){this.data.history.splice(oldIndex,1)}this.data.history.unshift(newItem);if(this.data.history.length>MAX_RECENTS){this.data.history.length=MAX_RECENTS}save(this.storeName,this.data)}async validate(apiProxy){if(this.data.history.length===0){return false}const ids=this.data.history.map((x=>x.base.visualContent.id));const{selectedGifs:selectedGifs}=await apiProxy.getGifsByIds(ids);const map=new Map;selectedGifs.forEach((gif=>{map.set(gif.id,gif)}));const validGifHistory=this.data.history.filter((item=>map.has(item.base.visualContent.id)));const updated=validGifHistory.length!==this.data.history.length;if(updated){this.data.history=validGifHistory;save(this.storeName,this.data)}return updated}}const GIF_NUDGE_SHOWN_KEY="emoji-picker-gif-nudge-shown";export class GifNudgeHistoryStore{hasNudgeShown(){return window.localStorage.getItem(GIF_NUDGE_SHOWN_KEY)===true.toString()}setNudgeShown(value){window.localStorage.setItem(GIF_NUDGE_SHOWN_KEY,value.toString())}static getInstance(){return new GifNudgeHistoryStore}}